INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000034'::uuid, 'In a multi-catch block ''catch (IOException | SQLException ex)'', what restriction applies to the variable ''ex''?', '{"A": "ex must be thrown again", "B": "ex is implicitly final and cannot be reassigned", "C": "It only catches IOException", "D": "IOException must be a subclass of SQLException"}'::jsonb, 'B', 'Multi-catch parameters are implicitly final, and the listed exception types cannot have a parent-child relationship.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
