INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000035'::uuid, 'Why should application code generally NOT catch ''java.lang.Error'' (such as OutOfMemoryError)?', '{"A": "Error is private", "B": "Catching Error is a syntax error", "C": "Errors are checked exceptions", "D": "Errors represent serious JVM-level failures that applications usually cannot recover from"}'::jsonb, 'D', 'Errors indicate abnormal JVM conditions (e.g., OutOfMemoryError, StackOverflowError) outside normal recovery.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000035'::uuid, 'When should you use a checked exception vs an unchecked exception?', '{"A": "Always use Error", "B": "Checked for programmer bugs; unchecked for network outages", "C": "Checked when the caller can reasonably recover; unchecked for programming/invariant bugs (e.g., null/invalid argument)", "D": "Always use checked exceptions"}'::jsonb, 'C', 'Effective Java recommends checked exceptions for recoverable conditions and RuntimeExceptions for programming errors.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000036'::uuid, 'When wrapping a low-level exception in a custom exception, why should you pass the original exception as the ''cause'' (''super(message, cause)'')?', '{"A": "To preserve the root-cause stack trace for debugging and logging", "B": "To convert checked to Error", "C": "To hide the stack trace", "D": "To avoid writing a message"}'::jsonb, 'A', 'Exception chaining keeps the underlying cause and stack trace intact instead of swallowing diagnostic details.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000036'::uuid, 'What constructors are best practice to include in a custom exception class?', '{"A": "Only a no-arg constructor", "B": "Constructors accepting (String message) and (String message, Throwable cause)", "C": "Only a static factory", "D": "A private constructor"}'::jsonb, 'B', 'Providing message and message+cause constructors follows standard JDK exception conventions.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000034'::uuid, 'What happens if an exception is thrown inside a ''catch'' block and there is a ''finally'' block?', '{"A": "finally is skipped", "B": "The JVM terminates", "C": "finally still executes before the exception propagates to the caller", "D": "The exception is swallowed"}'::jsonb, 'C', 'finally executes even when a catch block throws or rethrows an exception.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000035'::uuid, 'What does ''swallowing an exception'' (an empty catch block ''catch (Exception e) {}'') cause in production?', '{"A": "Automatic retry", "B": "Silent failures that hide bugs and corrupt state without logs", "C": "Compile warning", "D": "Faster performance"}'::jsonb, 'B', 'Empty catch blocks hide failures and make root-cause diagnosis nearly impossible.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000036'::uuid, 'In Spring Boot REST APIs, how do custom domain exceptions (e.g., ResourceNotFoundException) typically map to HTTP status codes?', '{"A": "Using finally blocks in controllers", "B": "By extending HttpServlet", "C": "They always return 500", "D": "Using @RestControllerAdvice / @ExceptionHandler to return 404/400/409 responses"}'::jsonb, 'D', 'Global exception handlers translate domain exceptions into clean HTTP responses.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000034'::uuid, 'In try-with-resources, if BOTH the try body and resource.close() throw exceptions, what happens to the close() exception?', '{"A": "Both are lost", "B": "The close() exception overwrites the try exception", "C": "Only close() is thrown", "D": "The try exception is thrown as primary, and the close() exception is attached as a suppressed exception (getSuppressed())"}'::jsonb, 'D', 'try-with-resources preserves the primary exception from the try block and records close() failures via Throwable.addSuppressed().', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000034'::uuid, 'In what order are multiple resources closed in ''try (R1 r1 = ...; R2 r2 = ...)''?', '{"A": "r1 first, then r2", "B": "Random", "C": "Reverse order of declaration: r2 first, then r1", "D": "Parallel"}'::jsonb, 'C', 'Resources are closed in LIFO (reverse declaration) order so dependent outer resources close after inner ones.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000034'::uuid, 'Why is putting a ''return'' statement inside a ''finally'' block an anti-pattern?', '{"A": "It runs before try", "B": "It overrides any return value or thrown exception from the try/catch blocks, silently discarding exceptions", "C": "It fails to compile", "D": "It leaks memory"}'::jsonb, 'B', 'A return in finally abruptly completes the method and swallows any active exception from try or catch.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000035'::uuid, 'Why is filling in the stack trace (Throwable.fillInStackTrace()) the main performance cost of creating exceptions in hot paths?', '{"A": "Walking the current thread''s call stack frames to capture stack trace elements", "B": "Disk I/O", "C": "Acquiring a global lock", "D": "String concatenation of the message"}'::jsonb, 'A', 'Constructing an exception walks the call stack, which is expensive; therefore exceptions should not be used for normal control flow.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000036'::uuid, 'When a custom exception is used solely for high-throughput internal signaling where stack traces aren''t needed, how can its cost be reduced?', '{"A": "Use Error instead", "B": "Override fillInStackTrace() to return ''this'' (or pass writableStackTrace = false to super)", "C": "Catch Throwable in main", "D": "Make all fields static"}'::jsonb, 'B', 'The 4-arg Throwable constructor with writableStackTrace=false skips stack trace capture.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'exception-handling'), '70000000-0000-0000-0000-000000000035'::uuid, 'In a ''try (var r = open())'' block, if ''open()'' itself throws an exception, is ''r.close()'' called?', '{"A": "Compile error", "B": "Yes", "C": "No, because the resource was never successfully initialized", "D": "Yes, with null"}'::jsonb, 'C', 'try-with-resources only calls close() on resources whose initialization completed without throwing.', 'ADVANCED', TRUE);

