VALUES ((SELECT id FROM skills WHERE slug = 'list-set-map'), '70000000-0000-0000-0000-000000000039'::uuid, 'Why does ConcurrentHashMap disallow null keys and null values while HashMap permits them?', '{"A": "It is a compiler bug", "B": "In concurrent code, map.get(k) == null would be ambiguous between ''key absent'' and ''value is null'', and containsKey+get isn''t atomic", "C": "Nulls cannot be hashed", "D": "ConcurrentHashMap uses TreeMap"}'::jsonb, 'B', 'Null values create check-then-act ambiguity in multi-threaded lookups.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'list-set-map'), '70000000-0000-0000-0000-000000000038'::uuid, 'In a TreeSet with a Comparator that is inconsistent with equals() (e.g., comparing only String length), what does treeSet.add("ab") do if "xy" is already present?', '{"A": "Throws ClassCastException", "B": "Replaces \"xy\"", "C": "Adds \"ab\" because equals() is false", "D": "Rejects \"ab\" because TreeSet uses compare()==0 to define equality, not equals()"}'::jsonb, 'D', 'SortedSet/TreeSet defines element identity via compareTo/Comparator == 0 rather than equals().', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'list-set-map'), '70000000-0000-0000-0000-000000000037'::uuid, 'What happens when you call ''list.subList(1, 4).clear()'' on an ArrayList?', '{"A": "Only clears the copy", "B": "Clears the entire list", "C": "Throws UnsupportedOperationException", "D": "Removes elements 1..3 directly from the backing ArrayList because subList returns a backed view"}'::jsonb, 'D', 'List.subList returns a live view backed by the original list; structural changes on the subList mutate the parent list.', 'ADVANCED', TRUE);

-- Skill: hashmap-internals
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'Which two Object methods must be properly implemented by keys stored in a HashMap?', '{"A": "hashCode() and equals()", "B": "toString() and clone()", "C": "wait() and notify()", "D": "compareTo() and finalize()"}'::jsonb, 'A', 'HashMap uses hashCode() to pick a bucket and equals() to match keys inside that bucket.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'What is a hash collision in a HashMap?', '{"A": "A null key", "B": "Two keys that are equal", "C": "Two distinct keys whose hashes map to the same bucket index", "D": "A full HashMap"}'::jsonb, 'C', 'Because the bucket array is finite, different keys can land in the same bucket index.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'If ''a.equals(b)'' is true, what MUST be true about ''a.hashCode()'' and ''b.hashCode()''?', '{"A": "One must be 0", "B": "They must be prime", "C": "They must be equal", "D": "They must be different"}'::jsonb, 'C', 'The hashCode contract mandates that equal objects return identical hash codes.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'What is the default initial capacity (number of buckets) of a Java HashMap?', '{"A": "32", "B": "10", "C": "8", "D": "16"}'::jsonb, 'D', 'HashMap starts with a default table capacity of 16 buckets (allocated lazily on first put).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'What is the default load factor of a Java HashMap?', '{"A": "1.0", "B": "0.25", "C": "0.5", "D": "0.75"}'::jsonb, 'D', 'The default load factor 0.75 balances space efficiency and lookup speed (threshold = 16 * 0.75 = 12).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'Before Java 8, what data structure did a HashMap bucket use to store colliding entries?', '{"A": "Binary heap", "B": "Stack", "C": "Singly linked list", "D": "ArrayList"}'::jsonb, 'C', 'Colliding entries were chained in a linked list within each bucket.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'What is the average time complexity of HashMap.get(key) and HashMap.put(key, value)?', '{"A": "O(n log n)", "B": "O(log n)", "C": "O(1)", "D": "O(n)"}'::jsonb, 'C', 'With a well-distributed hash function, HashMap provides O(1) expected time for get, put, and remove.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'What happens to HashMap''s capacity when the number of entries exceeds ''capacity * loadFactor''?', '{"A": "It resizes (doubles capacity) and rehashes existing entries into the new bucket array", "B": "It throws OutOfMemoryError", "C": "It rejects new entries", "D": "It converts to a TreeMap"}'::jsonb, 'A', 'Resizing doubles the power-of-two capacity and redistributes entries across the larger table.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'If two objects have the SAME hashCode(), must ''a.equals(b)'' be true?', '{"A": "Only for Strings", "B": "No; unequal objects can collide and share the same hashCode", "C": "Only for Integers", "D": "Yes, always"}'::jsonb, 'B', 'Equal objects must have equal hashCodes, but equal hashCodes do NOT imply equal objects.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'Why does HashMap apply a supplemental hash perturbation ''(h = key.hashCode()) ^ (h >>> 16)''?', '{"A": "To spread high-bit entropy down into low bits when indexing small power-of-two tables via ''(n - 1) & hash''", "B": "To make hashCode positive", "C": "To speed up String.equals", "D": "To encrypt keys"}'::jsonb, 'A', 'Because bucket index uses only the lowest log2(n) bits, XORing the upper 16 bits reduces collisions for hashes that vary mainly in higher bits.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'Why is String an ideal HashMap key?', '{"A": "String is immutable and caches its hashCode after first computation", "B": "String has no equals()", "C": "String bypasses buckets", "D": "String is mutable"}'::jsonb, 'A', 'Immutability prevents the key''s hash from changing after insertion, and cached hashCode makes repeated lookups fast.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'In Java 8+, what happens when a single HashMap bucket''s linked list grows beyond TREEIFY_THRESHOLD (8)?', '{"A": "It throws HashCollisionException", "B": "If total table capacity is >= 64, the bucket converts from a linked list to a balanced Red-Black tree", "C": "It converts the whole map to ArrayList", "D": "It deletes half the bucket"}'::jsonb, 'B', 'Treeification improves worst-case bucket lookup from O(n) to O(log n) when many keys collide (provided capacity >= MIN_TREEIFY_CAPACITY = 64).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'What is the UNTREEIFY_THRESHOLD in Java 8+ HashMap?', '{"A": "When a tree bin shrinks to 6 or fewer nodes (during resize), it converts back to a linked list", "B": "16", "C": "Trees never convert back", "D": "0"}'::jsonb, 'A', 'Hysteresis between treeify (8) and untreeify (6) avoids thrashing between list and tree.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'How does HashMap compute the bucket index from ''hash'' when capacity ''n'' is a power of two?', '{"A": "(n - 1) & hash (bitwise AND)", "B": "hash % n", "C": "hash / n", "D": "hash ^ n"}'::jsonb, 'A', 'When n is a power of two, (n - 1) & hash is equivalent to modulo for non-negative values and executes in a single fast bitwise instruction.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'If you pass ''new HashMap<>(10)'' as initial capacity, what actual table capacity does HashMap allocate?', '{"A": "20", "B": "10", "C": "16 (the next power of two >= 10)", "D": "12"}'::jsonb, 'C', 'tableSizeFor(cap) rounds up to the nearest power of two so bitwise masking (n - 1) & hash works.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'Which bucket index does HashMap always place a ''null'' key into?', '{"A": "Bucket n - 1", "B": "Bucket 0 (because hash(null) returns 0)", "C": "A separate field outside the array", "D": "Random bucket"}'::jsonb, 'B', 'hash(null) returns 0, so a null key is always stored in bucket 0.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'In HashMap.put(k, v), if a matching key already exists in the bucket, what does put() return?', '{"A": "null", "B": "The new value", "C": "true", "D": "The previous value associated with that key"}'::jsonb, 'D', 'put() replaces the old value and returns it (or returns null if there was no prior mapping or the prior value was null).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'Why is HashMap''s internal array allocated lazily on the first put() rather than in the constructor?', '{"A": "To force loadFactor to 1.0", "B": "Because constructors cannot allocate arrays", "C": "To avoid allocating memory for empty HashMaps that are never populated", "D": "To support concurrency"}'::jsonb, 'C', 'Lazy allocation saves heap space when maps are constructed and remain empty.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'During Java 8+ HashMap resizing (doubling from n to 2n), how does a node''s bucket index change without recomputing hashCode()?', '{"A": "It moves to a random index", "B": "hashCode() must be called again", "C": "It either stays at index j or moves to j + n depending on a single bit ''(e.hash & oldCap) == 0''", "D": "It always moves to index + n"}'::jsonb, 'C', 'Because capacity doubles (adds one high bit to the mask), checking e.hash & oldCap splits each bucket cleanly into low (j) and high (j + oldCap) lists.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'In Java 8+, if two keys collide in a treeified bucket and their classes do NOT implement Comparable, how does the Red-Black tree order them?', '{"A": "Throws ClassCastException", "B": "Falls back to class name comparison and finally System.identityHashCode tie-breaking", "C": "Drops the second key", "D": "Keeps them in a linked list"}'::jsonb, 'B', 'HashMap''s tieBreakOrder compares class names and System.identityHashCode so even non-Comparable keys work in tree bins.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'Why could concurrent unsynchronized puts into a Java 7 HashMap cause an infinite loop (100% CPU) during resize?', '{"A": "Java 7 allowed negative capacity", "B": "Java 7 used recursion in get()", "C": "Java 7 had no load factor", "D": "Java 7 reversed linked list nodes while transferring to the new table, creating a circular linked list under race conditions"}'::jsonb, 'D', 'Java 8 preserves insertion order during resize (loHead/loTail, hiHead/hiTail) avoiding cycles, though HashMap is still NOT thread-safe.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000042'::uuid, 'If you know a HashMap will hold 100 entries with default loadFactor 0.75, what initial capacity avoids any resize?', '{"A": "100", "B": "128", "C": "75", "D": "At least ceil(100 / 0.75) = 134 -> HashMap rounds up to 256 (or use HashMap.newHashMap(100) in Java 19+)"}'::jsonb, 'D', 'With capacity 128, threshold is 128 * 0.75 = 96 (< 100), so 128 would still resize once; 256 (or Java 19 HashMap.newHashMap(100)) avoids resizing.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000041'::uuid, 'What is the worst-case time complexity of HashMap.get() in Java 8+ if all N keys hash to the exact same bucket?', '{"A": "O(1)", "B": "O(log N) once the bucket treeifies (assuming capacity >= 64)", "C": "O(N)", "D": "O(N^2)"}'::jsonb, 'B', 'Treeification caps worst-case lookup at O(log N) instead of Java 7''s O(N), mitigating hash-flooding DoS attacks.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'hashmap-internals'), '70000000-0000-0000-0000-000000000040'::uuid, 'If a custom key class uses a mutable field inside hashCode() and that field changes after put(), what happens on get() and remove()?', '{"A": "HashMap rehashes automatically", "B": "Both fail to find the entry, causing a logical memory leak where the entry stays in the map unreachable by key", "C": "Both succeed", "D": "HashMap throws IllegalStateException"}'::jsonb, 'B', 'Always use immutable fields for Map key hashCode/equals.', 'ADVANCED', TRUE);

-- Skill: sorting-searching
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'Which interface does a class implement to define its own ''natural ordering'' via compareTo(T o)?', '{"A": "Sortable<T>", "B": "Comparator<T>", "C": "Comparable<T>", "D": "Orderable<T>"}'::jsonb, 'C', 'Comparable<T> defines compareTo(T) inside the class itself for natural ordering.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'Which interface allows defining external or multiple custom sort orders (e.g., sort by name or by salary)?', '{"A": "Serializable", "B": "Comparator<T>", "C": "Comparable<T>", "D": "Iterable<T>"}'::jsonb, 'B', 'Comparator<T> defines compare(T o1, T o2) externally without modifying the element class.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'What does ''a.compareTo(b)'' return when ''a'' should come BEFORE ''b'' in ascending order?', '{"A": "A positive integer", "B": "0", "C": "true", "D": "A negative integer"}'::jsonb, 'D', 'Negative means a < b, zero means a == b, positive means a > b.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'What precondition MUST hold before running binary search on an array or list?', '{"A": "It must contain unique elements", "B": "Elements must be positive", "C": "Its length must be a power of two", "D": "It must already be sorted in the same order"}'::jsonb, 'D', 'Binary search relies on monotonic ordering to discard half the search space each step.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'Which standard library method performs binary search on a sorted int[] array?', '{"A": "Arrays.binarySearch(arr, key)", "B": "Arrays.search(arr, key)", "C": "Collections.find(arr, key)", "D": "arr.binarySearch(key)"}'::jsonb, 'A', 'Arrays.binarySearch (for arrays) and Collections.binarySearch (for Lists) implement binary search.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'What is the time complexity of linear search on an unsorted array of n elements?', '{"A": "O(log n)", "B": "O(n)", "C": "O(n^2)", "D": "O(1)"}'::jsonb, 'B', 'In the worst case, linear search inspects all n elements.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'What is the time complexity of binary search on a sorted array of n elements?', '{"A": "O(n log n)", "B": "O(1)", "C": "O(n)", "D": "O(log n)"}'::jsonb, 'D', 'Halving the search interval each comparison takes O(log n) steps.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'What is the average and worst-case time complexity of Bubble Sort?', '{"A": "O(n log n)", "B": "O(log n)", "C": "O(n)", "D": "O(n^2)"}'::jsonb, 'D', 'Bubble sort uses nested passes over the array, yielding O(n^2) comparisons in average and worst cases.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'How do you sort a List<Employee> by department ascending, then by salary descending using Java 8+ Comparators?', '{"A": "Collections.sort(list, true)", "B": "Comparator.reverse(Employee::getDept)", "C": "Comparator.comparing(Employee::getDept).thenComparing(Comparator.comparingDouble(Employee::getSalary).reversed())", "D": "list.sort(Employee::getDept)"}'::jsonb, 'C', 'Comparator.comparing().thenComparing(...) cleanly chains multi-key sorting.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'Why is ''return a.id - b.id;'' inside a Comparator dangerous for arbitrary ints?', '{"A": "It throws ArithmeticException", "B": "It is too slow", "C": "Integer overflow when subtracting large positive and negative ints (e.g., Integer.MIN_VALUE - 1) flips the sign", "D": "Comparators cannot return negative numbers"}'::jsonb, 'C', 'Use Integer.compare(a.id, b.id) instead of subtraction to avoid two''s-complement overflow.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'What does ''Arrays.binarySearch(arr, key)'' return when ''key'' is NOT found?', '{"A": "-1", "B": "-(insertionPoint) - 1", "C": "0", "D": "Throws NoSuchElementException"}'::jsonb, 'B', 'Returning -(insertionPoint) - 1 distinguishes ''not found'' (< 0) from index 0 and tells you where the key would be inserted.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'Why is ''int mid = low + (high - low) / 2;'' preferred over ''(low + high) / 2'' in binary search?', '{"A": "It avoids division by zero", "B": "It is faster", "C": "It works on unsorted arrays", "D": "It prevents signed integer overflow when low + high exceeds Integer.MAX_VALUE"}'::jsonb, 'D', 'For very large indices, low + high can overflow to a negative int, causing ArrayIndexOutOfBoundsException.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'What is a ''stable'' sorting algorithm?', '{"A": "One that preserves the relative order of elements with equal keys", "B": "One that always runs in O(n)", "C": "One that never throws exceptions", "D": "One that uses O(1) space"}'::jsonb, 'A', 'Stability matters when sorting by multiple criteria (e.g., sort by name, then stably sort by department).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'Which sorting algorithm does Java''s ''Arrays.sort(Object[])'' and ''Collections.sort(List)'' use?', '{"A": "Heap Sort", "B": "Selection Sort", "C": "Bubble Sort", "D": "TimSort (hybrid Merge Sort + Insertion Sort, stable, O(n log n) worst-case)"}'::jsonb, 'D', 'Object sorting in Java uses TimSort because it is stable and exploits already-sorted runs.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'Which sorting algorithm does Java''s ''Arrays.sort(int[])'' (primitives) use?', '{"A": "Bubble Sort", "B": "Radix Sort", "C": "TimSort", "D": "Dual-Pivot Quicksort (not stable, O(1) extra stack space average, very fast on primitives)"}'::jsonb, 'D', 'Stability is irrelevant for identical primitive values, so Dual-Pivot Quicksort gives superior cache locality and speed.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'Compare Merge Sort and Quicksort in terms of worst-case time complexity and auxiliary space.', '{"A": "Quicksort is stable", "B": "Merge Sort: O(n log n) worst-case time, O(n) space; Quicksort: O(n^2) worst-case time, O(log n) avg stack space", "C": "Merge Sort is O(n^2)", "D": "Both are O(1) space and O(n log n) worst-case"}'::jsonb, 'B', 'Merge Sort guarantees O(n log n) worst-case with O(n) extra memory, whereas Quicksort is in-place (O(log n) stack) with O(n^2) worst-case on bad pivots.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'Why is binary search inefficient on a Java LinkedList even if the LinkedList is sorted?', '{"A": "LinkedList cannot be sorted", "B": "Collections.binarySearch throws on LinkedList", "C": "LinkedList lacks O(1) random access, so reaching mid takes O(n) traversal, degrading total time to O(n)", "D": "LinkedList doesn''t support Comparable"}'::jsonb, 'C', 'Binary search needs O(1) indexed access (RandomAccess) to achieve O(log n) time.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'How should you handle null elements safely in a Comparator?', '{"A": "Cast null to String", "B": "Return 0 on null", "C": "Nulls sort automatically", "D": "Wrap with Comparator.nullsFirst(comp) or Comparator.nullsLast(comp)"}'::jsonb, 'D', 'nullsFirst/nullsLast cleanly prevents NullPointerException when sorting lists that may contain null entries.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'What breaks if a Comparator violates transitivity (e.g., A < B, B < C, but C < A)?', '{"A": "JVM crashes", "B": "Array becomes reversed", "C": "Nothing", "D": "TimSort throws IllegalArgumentException: Comparison method violates its general contract"}'::jsonb, 'D', 'TimSort detects contract violations (reflexivity, antisymmetry, transitivity) and throws IllegalArgumentException.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'In binary search, how do you find the FIRST (leftmost) occurrence of a target in a sorted array with duplicates?', '{"A": "Return mid immediately when arr[mid] == target", "B": "When arr[mid] == target, record mid as a candidate and continue searching left (high = mid - 1)", "C": "Run linear search from 0", "D": "Search right (low = mid + 1)"}'::jsonb, 'B', 'Lower-bound binary search narrows high = mid - 1 upon match to locate the earliest index.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'What is the lower bound (Omega) on comparisons required by any comparison-based sorting algorithm for n elements?', '{"A": "Omega(log n)", "B": "Omega(n log n)", "C": "Omega(n^2)", "D": "Omega(n)"}'::jsonb, 'B', 'A decision tree over n! permutations has height >= log2(n!) = Omega(n log n); only non-comparison sorts like Counting/Radix Sort can beat it on restricted keys.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000044'::uuid, 'Can binary search be applied to ''binary search on the answer'' problems (monotonic predicate) without an explicit array?', '{"A": "Yes; any monotonic boolean predicate f(x) over a bounded integer/real range can be binary searched in O(log(range))", "B": "No, binary search requires an array", "C": "Only on Strings", "D": "Only with HashMap"}'::jsonb, 'A', 'Parametric search finds the minimum/maximum feasible value (e.g., minimum capacity to ship packages in D days) using a monotonic check.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000045'::uuid, 'Why is TimSort''s best-case time complexity O(n) on already-sorted or nearly-sorted input?', '{"A": "It detects existing ascending/descending runs in a single linear pass and performs minimal merges", "B": "It skips comparisons entirely", "C": "It switches to Bubble Sort", "D": "It uses a hash table"}'::jsonb, 'A', 'TimSort identifies natural runs; if the entire array is one run, no merging is needed—taking O(n) time.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sorting-searching'), '70000000-0000-0000-0000-000000000043'::uuid, 'Why should ''a.compareTo(b) == 0'' generally be consistent with ''a.equals(b)''?', '{"A": "Otherwise sorted collections like TreeSet/TreeMap behave differently from HashSet/HashMap for the same objects", "B": "compareTo is called by HashMap", "C": "Java compiler enforces it", "D": "Otherwise Arrays.sort throws an exception"}'::jsonb, 'A', 'TreeSet uses compareTo==0 while HashSet uses equals(), so inconsistency causes subtle bugs across collection types (as seen with BigDecimal("1.0") vs BigDecimal("1.00")).', 'ADVANCED', TRUE);

-- Skill: relational-database-concepts
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'In a relational database, what do rows (tuples) and columns (attributes) represent?', '{"A": "Rows represent indexes; columns represent queries", "B": "Rows represent individual records; columns represent attributes/fields of each record", "C": "Rows represent tables; columns represent databases", "D": "They are interchangeable"}'::jsonb, 'B', 'Each row is one entity instance, and each column defines a typed attribute across all rows.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'What is a database schema?', '{"A": "A single row of data", "B": "A SQL SELECT query", "C": "A backup file", "D": "The formal blueprint defining tables, columns, data types, constraints, and relationships"}'::jsonb, 'D', 'A schema describes the structure and rules of the database objects.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'Why are strongly typed columns (e.g., INT, UUID, TIMESTAMPTZ) important in relational tables?', '{"A": "They enforce valid data domains at storage time and optimize indexing/comparisons", "B": "They disable constraints", "C": "They allow storing anything anywhere", "D": "They make queries slower"}'::jsonb, 'A', 'Column data types prevent invalid values (e.g., text in a date column) and enable compact storage.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'What is a Primary Key (PK)?', '{"A": "A column that can have duplicate values", "B": "Any indexed text column", "C": "A password column", "D": "A column (or combination of columns) that uniquely identifies every row and cannot be NULL"}'::jsonb, 'D', 'A primary key guarantees entity integrity: unique and non-null for every row.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'What is a Candidate Key?', '{"A": "Any non-unique column", "B": "Any minimal set of columns capable of uniquely identifying a row (one of which is chosen as the Primary Key)", "C": "A nullable column", "D": "A foreign key awaiting deletion"}'::jsonb, 'B', 'A table may have multiple candidate keys (e.g., user id and email); one becomes the PK and others become UNIQUE keys.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'How is a One-to-Many (1:N) relationship represented in a relational database?', '{"A": "By placing a Foreign Key on the ''many'' side referencing the ''one'' side''s Primary Key", "B": "By storing comma-separated IDs in a text column", "C": "By creating two identical tables", "D": "By duplicating the parent row for every child"}'::jsonb, 'A', 'Each child row holds a foreign key pointing to its single parent row.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'How is a Many-to-Many (M:N) relationship modeled in a relational database?', '{"A": "Using a separate junction (bridge/associative) table containing foreign keys to both tables", "B": "It cannot be modeled in SQL", "C": "Storing arrays of IDs", "D": "Two foreign keys inside one table only"}'::jsonb, 'A', 'A junction table decomposes an M:N relationship into two 1:N relationships.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'What is a One-to-One (1:1) relationship example in the Upskill schema?', '{"A": "tracks to skills", "B": "users to milestone_attempts", "C": "skills to skill_roadmaps (where skill_id is UNIQUE on skill_roadmaps)", "D": "skills to questions"}'::jsonb, 'C', 'Placing a UNIQUE Foreign Key on the child table enforces a 1:1 relationship.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'What does SQL ''NULL'' represent in a relational table?', '{"A": "Unknown or missing value (not equal to anything, even another NULL)", "B": "False", "C": "An empty string ''''", "D": "Zero (0)"}'::jsonb, 'A', 'NULL means missing/unknown; in SQL three-valued logic, NULL = NULL evaluates to UNKNOWN, so use IS NULL.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'What is a Superkey vs a Candidate Key?', '{"A": "A Superkey is any column set that uniquely identifies rows (may include extra unnecessary columns); a Candidate Key is a minimal Superkey", "B": "A Candidate Key allows duplicates", "C": "They are exact opposites", "D": "A Superkey must be UUID"}'::jsonb, 'A', 'Removing any attribute from a candidate key destroys its uniqueness, whereas a superkey may contain redundant columns.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'What is a Composite Key?', '{"A": "An auto-increment integer", "B": "An encrypted key", "C": "A key that references two tables", "D": "A primary or unique key formed by combining two or more columns (e.g., (user_id, skill_id))"}'::jsonb, 'D', 'Composite keys enforce uniqueness across a combination of columns, common in junction tables.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'Compare Surrogate Keys (e.g., UUID/BIGSERIAL) vs Natural Keys (e.g., email/SSN).', '{"A": "Natural keys are always faster to join", "B": "Natural keys never change", "C": "Surrogate keys cannot be indexed", "D": "Surrogate keys have no business meaning and remain immutable even if user attributes like email change"}'::jsonb, 'D', 'Surrogate keys decouple database identity from mutable business fields.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'What is a self-referencing (unary) relationship?', '{"A": "A table with a Foreign Key referencing its own Primary Key (e.g., roadmap_nodes.parent_node_id -> roadmap_nodes.id)", "B": "Two tables with the same name", "C": "A table with no keys", "D": "A view querying itself"}'::jsonb, 'A', 'Self-referencing FKs represent hierarchies and trees within a single table.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'Why is storing comma-separated IDs in a single VARCHAR column (e.g., ''1,4,9'') an anti-pattern?', '{"A": "It violates 1NF, breaks foreign key constraints, and prevents efficient indexed joins", "B": "It uses less space", "C": "PostgreSQL rejects commas", "D": "VARCHAR cannot hold commas"}'::jsonb, 'A', 'Non-atomic lists destroy referential integrity and force slow string-splitting scans.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'In PostgreSQL, how does a UNIQUE constraint treat multiple NULL values by default?', '{"A": "Rejects the second NULL", "B": "Converts NULL to empty string", "C": "Throws an error on first NULL", "D": "Allows multiple NULLs because NULLs are considered distinct unless NULLS NOT DISTINCT is specified"}'::jsonb, 'D', 'By SQL standard (and PostgreSQL default), NULL != NULL so multiple rows can have NULL in a UNIQUE column.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'What is ''cardinality'' vs ''optionality'' (modality) in an ER relationship?', '{"A": "Optionality is index type", "B": "Cardinality is number of columns", "C": "Both mean data type", "D": "Cardinality is max occurrences (1 vs many); optionality is whether participation is mandatory (1) or optional (0)"}'::jsonb, 'D', 'Together they express 0..1, 1..1, 0..N, or 1..N participation rules.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'What is the difference between DDL and DML in SQL?', '{"A": "They are identical", "B": "DML creates tables", "C": "DDL defines structure (CREATE, ALTER, DROP); DML manipulates data (SELECT, INSERT, UPDATE, DELETE)", "D": "DDL is for PostgreSQL only"}'::jsonb, 'C', 'Data Definition Language manages schema objects; Data Manipulation Language queries and modifies rows.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'When using UUID v4 as a Primary Key in PostgreSQL, what is ''gen_random_uuid()''?', '{"A": "A Java-only method", "B": "A hash function for passwords", "C": "A sequential integer generator", "D": "A built-in PostgreSQL 13+ function generating cryptographically random v4 UUIDs"}'::jsonb, 'D', 'PostgreSQL 13+ provides gen_random_uuid() natively without needing the uuid-ossp extension.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'Why can random UUID v4 primary keys cause B-tree index fragmentation / write amplification on very large tables compared to sequential IDs or UUID v7?', '{"A": "UUIDs cannot be compared", "B": "PostgreSQL cannot index UUIDs", "C": "UUIDs require full table locks", "D": "Random UUIDs insert into random B-tree leaf pages, causing page splits and lower cache hit rates, whereas monotonic keys append to the rightmost leaf"}'::jsonb, 'D', 'Random insertions dirty many index pages instead of appending sequentially; time-ordered UUID v7 mitigates this.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'In a junction table (e.g., milestone_attempt_questions), when should you use a surrogate UUID PK + UNIQUE(attempt_id, question_id) vs a composite PK?', '{"A": "JPA cannot map composite keys", "B": "Surrogate PKs remove the need for FKs", "C": "Surrogate UUID PK simplifies ORM (JPA @Id) and child references while UNIQUE(attempt_id, question_id) still enforces business uniqueness", "D": "Composite PKs are illegal in PostgreSQL"}'::jsonb, 'C', 'A surrogate UUID PK keeps JPA entity mapping simple while a composite UNIQUE constraint preserves relational uniqueness.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'What is PostgreSQL MVCC (Multi-Version Concurrency Control) at a high level?', '{"A": "Locking the entire table on every SELECT", "B": "Storing two copies of the database on disk", "C": "Running queries single-threaded", "D": "Keeping multiple row tuple versions with transaction IDs so readers never block writers and writers never block readers"}'::jsonb, 'D', 'MVCC provides snapshot isolation where SELECT sees a consistent point-in-time view without read locks.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000046'::uuid, 'In PostgreSQL, when should you prefer JSONB over normalized columns (and vice versa)?', '{"A": "JSONB cannot be indexed", "B": "Use JSONB for flexible/semi-structured payloads (like MCQ options or resource links) and normalized columns for FKs, constraints, and frequent joins", "C": "Normalized columns cannot store text", "D": "Always use JSONB for everything"}'::jsonb, 'B', 'Normalized columns give FK integrity and tight constraints; JSONB gives schema flexibility and GIN indexing.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000048'::uuid, 'What is a polymorphic association anti-pattern (e.g., entity_type + entity_id) and why does it hurt relational integrity?', '{"A": "A single entity_id column cannot have a Foreign Key constraint pointing to multiple different parent tables", "B": "PostgreSQL forbids VARCHAR + UUID", "C": "It requires two joins", "D": "It duplicates primary keys"}'::jsonb, 'A', 'Because a FK can reference only one target table, polymorphic columns lose database-enforced referential integrity.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'relational-database-concepts'), '70000000-0000-0000-0000-000000000047'::uuid, 'What does ''DEFERRABLE INITIALLY DEFERRED'' allow on a PostgreSQL constraint?', '{"A": "Runs the constraint asynchronously after commit", "B": "Applies only to NOT NULL", "C": "Disables the constraint permanently", "D": "Delays constraint checking until transaction COMMIT rather than immediately after each statement"}'::jsonb, 'D', 'Deferred constraints allow temporary intermediate violations (e.g., swapping two unique question_order values) within a single transaction.', 'ADVANCED', TRUE);

-- Skill: sql-fundamentals
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'Which SQL clause filters rows BEFORE any grouping occurs?', '{"A": "WHERE", "B": "ORDER BY", "C": "HAVING", "D": "GROUP BY"}'::jsonb, 'A', 'WHERE filters individual rows; HAVING filters aggregated groups.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'How do you correctly check for missing (NULL) values in a SQL WHERE clause?', '{"A": "WHERE score == NULL", "B": "WHERE score IS NULL", "C": "WHERE score = NULL", "D": "WHERE NULL(score)"}'::jsonb, 'B', 'Because NULL is unknown, ''= NULL'' always evaluates to UNKNOWN/false; you must use ''IS NULL'' or ''IS NOT NULL''.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'Which keyword sorts query results in descending order?', '{"A": "GROUP BY col DESC", "B": "SORT DESC", "C": "LIMIT DESC", "D": "ORDER BY col DESC"}'::jsonb, 'D', 'ORDER BY sorts ascending (ASC) by default; append DESC for descending order.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000050'::uuid, 'Which SQL statement modifies existing rows in a table?', '{"A": "INSERT INTO", "B": "UPDATE ... SET ... WHERE ...", "C": "MODIFY ROW", "D": "ALTER TABLE"}'::jsonb, 'B', 'UPDATE changes column values on existing rows matching the WHERE predicate.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000050'::uuid, 'What happens if you execute ''DELETE FROM milestone_questions;'' without a WHERE clause?', '{"A": "Syntax error", "B": "Every row in the table is deleted", "C": "Nothing is deleted", "D": "Only the first row is deleted"}'::jsonb, 'B', 'Omitting WHERE in DELETE or UPDATE applies the operation to all rows in the table.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'Which SQL keyword removes duplicate rows from a SELECT result set?', '{"A": "UNIQUE", "B": "SINGLE", "C": "ONLY", "D": "DISTINCT"}'::jsonb, 'D', 'SELECT DISTINCT returns unique combinations of the selected columns.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'Which aggregate function counts the number of rows in a group?', '{"A": "LEN(*)", "B": "TOTAL(*)", "C": "SUM(*)", "D": "COUNT(*)"}'::jsonb, 'D', 'COUNT(*) counts all rows in the group (including rows with NULLs in individual columns).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'What is the difference between WHERE and HAVING in a GROUP BY query?', '{"A": "They are identical", "B": "WHERE filters rows before grouping; HAVING filters groups after aggregation", "C": "HAVING runs before WHERE", "D": "WHERE can use SUM() and HAVING cannot"}'::jsonb, 'B', 'WHERE cannot reference aggregate functions like COUNT(*); HAVING filters the resulting groups.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'In PostgreSQL, how does ''ILIKE'' differ from ''LIKE''?', '{"A": "LIKE uses regex and ILIKE does not", "B": "ILIKE matches integers", "C": "There is no difference", "D": "ILIKE is case-insensitive pattern matching; LIKE is case-sensitive"}'::jsonb, 'D', 'PostgreSQL''s ILIKE performs case-insensitive wildcard matching (''%'' and ''_'').', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'Why should ''LIMIT 10 OFFSET 20'' ALWAYS be paired with an explicit ''ORDER BY''?', '{"A": "OFFSET fails without ORDER BY", "B": "Without ORDER BY, row order is non-deterministic, causing overlapping or skipped pages", "C": "ORDER BY makes OFFSET O(1)", "D": "PostgreSQL rejects LIMIT without ORDER BY"}'::jsonb, 'B', 'Without a deterministic ORDER BY (ideally including a unique tie-breaker like id), pagination results can shift between queries.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000050'::uuid, 'What does ''INSERT INTO ... RETURNING id;'' do in PostgreSQL?', '{"A": "Returns the generated id (or any column) of the newly inserted row in the same round-trip", "B": "Re-inserts the row", "C": "Only works with UPDATE", "D": "Rolls back the insert"}'::jsonb, 'A', 'PostgreSQL''s RETURNING clause avoids a separate SELECT after INSERT, UPDATE, or DELETE.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000050'::uuid, 'How does ''TRUNCATE TABLE t'' differ from ''DELETE FROM t''?', '{"A": "TRUNCATE keeps the rows", "B": "TRUNCATE deallocates table pages immediately (minimal logging, much faster) and cannot take a WHERE clause; DELETE removes rows individually and fires per-row triggers", "C": "DELETE drops the table", "D": "TRUNCATE cannot be rolled back in PostgreSQL"}'::jsonb, 'B', 'Note: in PostgreSQL, TRUNCATE IS transactional and can be rolled back, unlike in some other databases.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'How does ''COUNT(*)'' differ from ''COUNT(score)'' when some rows have ''score IS NULL''?', '{"A": "COUNT(*) ignores NULL rows", "B": "COUNT(*) counts all rows; COUNT(score) counts only rows where score IS NOT NULL", "C": "COUNT(score) throws an error on NULL", "D": "They return the exact same number"}'::jsonb, 'B', 'Aggregate functions like COUNT(col), SUM(col), and AVG(col) ignore NULL values, whereas COUNT(*) counts rows.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'Why does ''SELECT skill_id, difficulty, COUNT(*) FROM milestone_questions GROUP BY skill_id;'' fail in PostgreSQL?', '{"A": "''difficulty'' is neither in GROUP BY nor wrapped in an aggregate function", "B": "PostgreSQL requires HAVING", "C": "COUNT(*) cannot be used with two columns", "D": "GROUP BY only accepts integers"}'::jsonb, 'A', 'Every non-aggregated column in the SELECT list must appear in GROUP BY (unless functionally dependent on a PK in GROUP BY).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'What is the logical execution order of SQL clauses in a SELECT query?', '{"A": "SELECT -> FROM -> WHERE -> GROUP BY -> HAVING -> ORDER BY -> LIMIT", "B": "FROM -> SELECT -> WHERE -> GROUP BY", "C": "WHERE -> FROM -> SELECT -> ORDER BY", "D": "FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY -> LIMIT"}'::jsonb, 'D', 'Because SELECT runs after WHERE and GROUP BY, column aliases defined in SELECT cannot be used in WHERE.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'What does ''COALESCE(explanation, ''''No explanation provided'''')'' return?', '{"A": "Throws an error if explanation is NULL", "B": "Always returns the second argument", "C": "Concatenates both strings", "D": "Returns the first non-NULL argument from left to right"}'::jsonb, 'D', 'COALESCE evaluates arguments in order and returns the first one that is not NULL.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000050'::uuid, 'What does ''INSERT INTO ... ON CONFLICT (slug) DO NOTHING;'' do in PostgreSQL?', '{"A": "Skips inserting rows that would violate the unique constraint on slug without raising an error", "B": "Updates the conflicting row", "C": "Deletes the old row", "D": "Aborts the transaction"}'::jsonb, 'A', 'ON CONFLICT DO NOTHING provides idempotent seeding when a unique constraint already matches.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'Which query finds skills that have fewer than 24 active milestone questions?', '{"A": "SELECT s.id, COUNT(q.id) FROM skills s LEFT JOIN milestone_questions q ON q.skill_id = s.id AND q.is_active = TRUE GROUP BY s.id HAVING COUNT(q.id) < 24", "B": "SELECT DISTINCT skill_id HAVING COUNT(*) < 24", "C": "SELECT skill_id FROM milestone_questions WHERE COUNT(*) < 24", "D": "SELECT skill_id FROM milestone_questions GROUP BY skill_id WHERE COUNT(*) < 24"}'::jsonb, 'A', 'LEFT JOIN preserves skills with 0 questions, and HAVING COUNT(q.id) < 24 filters after grouping.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'Why is ''WHERE NOT IN (SELECT node_id FROM ...)'' dangerous if the subquery can return even ONE NULL?', '{"A": "It throws a runtime exception", "B": "In SQL three-valued logic, ''x NOT IN (1, NULL)'' evaluates to UNKNOWN for every row, returning 0 rows", "C": "NOT IN is deprecated", "D": "NULL is treated as 0"}'::jsonb, 'B', 'x <> 1 AND x <> NULL is UNKNOWN, so NOT IN fails silently on NULLs; use NOT EXISTS or filter ''WHERE node_id IS NOT NULL''.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'Why is keyset (cursor) pagination (''WHERE id > :lastId ORDER BY id LIMIT 20'') superior to large OFFSET pagination?', '{"A": "OFFSET locks the table", "B": "Keyset pagination doesn''t need ORDER BY", "C": "OFFSET only works up to 100", "D": "OFFSET must scan and discard all skipped rows (O(offset + limit)), whereas keyset uses an index seek in O(log n + limit)"}'::jsonb, 'D', 'Deep OFFSET queries degrade linearly as page numbers grow; keyset pagination stays fast at any depth.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'How does a Window Function (''COUNT(*) OVER (PARTITION BY skill_id)'') differ from ''GROUP BY skill_id''?', '{"A": "Window functions cannot use COUNT", "B": "GROUP BY is only for integers", "C": "GROUP BY collapses rows into one row per group; a window function keeps all original rows while computing aggregates across each partition", "D": "Window functions run before WHERE"}'::jsonb, 'C', 'Window functions compute per-partition values without collapsing detail rows.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000050'::uuid, 'In PostgreSQL, what happens on ''UPDATE milestone_attempt_questions SET selected_answer = ''''A'''' WHERE ...'' regarding MVCC storage?', '{"A": "It locks the entire database", "B": "It overwrites the tuple bytes in-place", "C": "PostgreSQL writes a new row version and marks the old version dead for later VACUUM cleanup", "D": "It deletes and recreates indexes only"}'::jsonb, 'C', 'UPDATE in PostgreSQL is internally a delete-mark + insert of a new tuple version (which autovacuum later reclaims).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000051'::uuid, 'In PostgreSQL, what does ''COUNT(*) FILTER (WHERE difficulty = ''''BEGINNER'''')'' achieve?', '{"A": "Deletes non-beginner rows", "B": "Creates a partial index", "C": "Filters the whole query", "D": "Performs a conditional aggregate count inside GROUP BY cleanly without CASE WHEN"}'::jsonb, 'D', 'The SQL-standard FILTER (WHERE ...) clause lets one GROUP BY query compute multiple conditional counts (BEGINNER, INTERMEDIATE, ADVANCED) in a single pass.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'sql-fundamentals'), '70000000-0000-0000-0000-000000000049'::uuid, 'Why can wrapping an indexed column in a function like ''WHERE LOWER(email) = ''''a@b.com'''''' prevent PostgreSQL from using a normal B-tree index on ''email''?', '{"A": "The B-tree stores raw ''email'' values, not LOWER(email), unless an expression index on LOWER(email) is created", "B": "LOWER() returns JSONB", "C": "PostgreSQL ignores indexes on VARCHAR", "D": "B-tree doesn''t support ''=''"}'::jsonb, 'A', 'Non-SARGable predicates hide the raw indexed column; create an expression index or use citext.', 'ADVANCED', TRUE);

-- Skill: joins-subqueries
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'What does an INNER JOIN return?', '{"A": "Only rows that have matching values in both joined tables", "B": "All rows from both tables", "C": "Only unmatched rows", "D": "All rows from the left table"}'::jsonb, 'A', 'INNER JOIN discards rows from either table that lack a match on the ON condition.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'What does a LEFT JOIN (LEFT OUTER JOIN) return when a left-table row has no match in the right table?', '{"A": "An error is thrown", "B": "The left row is preserved with NULLs filled in for all right-table columns", "C": "The left row is dropped", "D": "The right row is duplicated"}'::jsonb, 'B', 'LEFT JOIN keeps every row from the left table regardless of whether a match exists on the right.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'Which keyword specifies the matching condition between two joined tables?', '{"A": "LINK", "B": "MATCH", "C": "ON", "D": "WITH"}'::jsonb, 'C', 'JOIN ... ON a.id = b.a_id defines the join predicate.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'What is a subquery in SQL?', '{"A": "A query without a FROM clause", "B": "A query that only runs on views", "C": "A query inside another SQL query (enclosed in parentheses)", "D": "A failed query"}'::jsonb, 'C', 'A subquery (inner query) is nested inside an outer SELECT, INSERT, UPDATE, or DELETE statement.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'Which operator checks whether a subquery returns at least one row?', '{"A": "HAS", "B": "EXISTS", "C": "ANYROW", "D": "CONTAINS"}'::jsonb, 'B', 'EXISTS (subquery) evaluates to TRUE as soon as the subquery finds one matching row.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000054'::uuid, 'What is a self join in SQL?', '{"A": "A join without an ON clause", "B": "A union of two tables", "C": "Joining a table to itself using two distinct table aliases", "D": "Joining two identical databases"}'::jsonb, 'C', 'A self join compares rows within the same table (e.g., child node to parent node) using aliases like c and p.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000054'::uuid, 'Why are table aliases mandatory when writing a self join?', '{"A": "To make the query shorter only", "B": "To disambiguate which copy of the table each column reference belongs to", "C": "To enable indexing", "D": "PostgreSQL requires aliases on all tables"}'::jsonb, 'B', 'Without distinct aliases (e.g., child and parent), referencing ''roadmap_nodes.title'' would be ambiguous.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'What happens if you accidentally omit the ON condition in a CROSS JOIN?', '{"A": "Returns 0 rows", "B": "Returns only 1 row", "C": "Produces a Cartesian product (every row of table A paired with every row of table B)", "D": "Matches on primary keys automatically"}'::jsonb, 'C', 'A Cartesian product of 1,000 × 1,000 rows yields 1,000,000 rows.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'In a LEFT JOIN from ''skills s LEFT JOIN milestone_questions q ON q.skill_id = s.id'', what happens if you put ''AND q.is_active = TRUE'' in the WHERE clause vs the ON clause?', '{"A": "Putting it in WHERE filters out NULL-padded rows, turning the LEFT JOIN into an INNER JOIN; putting it in ON preserves skills with 0 active questions", "B": "WHERE is faster and preserves NULLs", "C": "No difference", "D": "Putting it in ON fails to compile"}'::jsonb, 'A', 'Filtering right-table columns in WHERE eliminates unmatched rows where q.is_active is NULL.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'How do you find rows in table A that have NO matching row in table B using a LEFT JOIN (anti-join)?', '{"A": "LEFT JOIN B ON A.id = B.a_id WHERE A.id IS NULL", "B": "INNER JOIN B ON A.id <> B.a_id", "C": "LEFT JOIN B ON A.id = B.a_id WHERE B.a_id IS NULL", "D": "RIGHT JOIN B"}'::jsonb, 'C', 'Unmatched left rows have NULL in the right table''s non-null PK/FK column, so WHERE B.id IS NULL isolates them.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'How does a correlated subquery differ from a non-correlated subquery?', '{"A": "Correlated subqueries cannot use WHERE", "B": "There is no difference", "C": "Non-correlated subqueries only return booleans", "D": "A non-correlated subquery runs once independently; a correlated subquery references a column from the outer query and conceptually evaluates per outer row"}'::jsonb, 'D', 'Correlated subqueries depend on outer-row values (e.g., WHERE ma.skill_id = s.id).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'What happens if a scalar subquery (used like ''WHERE skill_id = (SELECT id FROM skills ...)'') returns more than one row?', '{"A": "It returns NULL", "B": "It uses the first row", "C": "PostgreSQL throws an error: ''more than one row returned by a subquery used as an expression''", "D": "It treats it as IN"}'::jsonb, 'C', 'Scalar subqueries must return at most 1 row (0 rows becomes NULL).', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000054'::uuid, 'Write the join condition to pair each ''roadmap_nodes'' row with its immediate parent node title.', '{"A": "FROM roadmap_nodes c INNER JOIN roadmap_nodes p ON c.id = p.id", "B": "FROM roadmap_nodes c JOIN roadmap_nodes p ON c.roadmap_id = p.roadmap_id", "C": "FROM roadmap_nodes c LEFT JOIN roadmap_nodes p ON c.parent_node_id = p.id", "D": "FROM roadmap_nodes WHERE parent_node_id = id"}'::jsonb, 'C', 'Using LEFT JOIN ensures root nodes (where parent_node_id IS NULL) are still included in the output.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'What does a FULL OUTER JOIN return?', '{"A": "All rows from both tables, matching where possible and padding NULLs on whichever side has no match", "B": "Only unmatched rows", "C": "Cartesian product", "D": "Only matched rows"}'::jsonb, 'A', 'FULL OUTER JOIN combines LEFT JOIN and RIGHT JOIN.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'What is a CTE (Common Table Expression) defined with ''WITH cte_name AS (...)''?', '{"A": "An index type", "B": "A named temporary result set scoped to a single SQL statement that improves readability and modularity", "C": "A permanent table", "D": "A stored procedure"}'::jsonb, 'B', 'CTEs act like inline named views for a single query and also support recursion via WITH RECURSIVE.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'If table A has 3 rows with key 1 and table B has 4 rows with key 1, how many rows does ''A INNER JOIN B ON A.k = B.k'' produce?', '{"A": "7", "B": "3", "C": "12", "D": "4"}'::jsonb, 'C', 'Every matching row on the left pairs with every matching row on the right: 3 × 4 = 12 rows.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'Why is ''EXISTS (SELECT 1 FROM ...)'' often preferred over ''IN (SELECT ...)'' for checking existence against large tables?', '{"A": "IN cannot use indexes", "B": "EXISTS returns all columns", "C": "EXISTS short-circuits on the first matching row and is immune to NULL pitfalls", "D": "IN only works on integers"}'::jsonb, 'C', 'EXISTS stops scanning as soon as one match is found and avoids NULL-in-NOT-IN bugs.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000054'::uuid, 'If you join ''skills -> skill_roadmaps -> roadmap_nodes'', what happens if a skill has 5 nodes and you also join ''milestone_questions'' on skill_id without care?', '{"A": "Nothing", "B": "PostgreSQL rejects 3-table joins", "C": "Row multiplication (Cartesian fan-out between nodes and questions for the same skill)", "D": "Duplicate rows are auto-removed"}'::jsonb, 'C', 'Joining two independent 1:N children of the same parent multiplies their counts; aggregate or join via node_id instead.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000054'::uuid, 'How can you traverse an arbitrary-depth parent-child hierarchy in ''roadmap_nodes'' in a single PostgreSQL query?', '{"A": "Multiple fixed self joins", "B": "WITH RECURSIVE cte AS (base_roots UNION ALL recursive_children)", "C": "GROUP BY parent_node_id", "D": "CROSS JOIN"}'::jsonb, 'B', 'Recursive CTEs walk trees/DAGs of arbitrary depth starting from anchor roots (parent_node_id IS NULL).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'What does PostgreSQL''s ''LEFT JOIN LATERAL (...)'' enable that a standard JOIN cannot do?', '{"A": "Runs the join in parallel across servers", "B": "Allows the subquery on the right to reference columns from preceding tables on the left (e.g., fetch top-N per group)", "C": "Automatically caches results", "D": "Creates a temporary index"}'::jsonb, 'B', 'LATERAL evaluates a correlated subquery per left-hand row, ideal for ''top 3 attempts per user'' queries.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'What are the three physical join algorithms PostgreSQL''s query planner chooses between?', '{"A": "Nested Loop Join, Hash Join, Merge Join", "B": "Bubble Join, Quick Join, Binary Join", "C": "B-Tree Join, GIN Join, Heap Join", "D": "Left Join, Right Join, Inner Join"}'::jsonb, 'A', 'PostgreSQL picks Nested Loop (small/indexed lookups), Hash Join (medium/large unsorted equi-joins), or Merge Join (pre-sorted inputs).', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000053'::uuid, 'In PostgreSQL 12+, how are non-recursive CTEs (''WITH x AS (...)'') optimized by default?', '{"A": "Always materialized into a temp table", "B": "Never optimized", "C": "Cached across sessions", "D": "Inlined into the main query (unless WITH ... AS MATERIALIZED is specified), allowing predicate pushdown and index use"}'::jsonb, 'D', 'PostgreSQL 12+ folds non-materialized CTEs into the parent query plan automatically.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000052'::uuid, 'When writing an anti-duplication query for milestone questions, why is ''NOT EXISTS (SELECT 1 FROM milestone_attempt_questions maq JOIN milestone_attempts ma ...)'' safer than ''NOT IN (...)''?', '{"A": "NOT IN is invalid in PostgreSQL", "B": "NOT EXISTS handles NULLs safely and allows PostgreSQL to use a Hash Anti Join or Index Semi-Join", "C": "NOT IN only checks 100 rows", "D": "NOT EXISTS sorts the table"}'::jsonb, 'B', 'NOT EXISTS avoids NULL traps and optimizes cleanly to an Anti Join plan.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'joins-subqueries'), '70000000-0000-0000-0000-000000000054'::uuid, 'In a recursive CTE over a graph that might accidentally contain a cycle, how do you prevent infinite recursion in PostgreSQL?', '{"A": "Add LIMIT 10", "B": "Use INNER JOIN", "C": "PostgreSQL stops after 5 levels automatically", "D": "Use PostgreSQL 14+ ''CYCLE id SET is_cycle USING path'' or track visited IDs in an array ''WHERE NOT (n.id = ANY(path))''"}'::jsonb, 'D', 'Tracking visited node IDs in a path array or using the CYCLE clause terminates cycles safely.', 'ADVANCED', TRUE);

-- Skill: primary-foreign-keys
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000055'::uuid, 'What two properties does a PRIMARY KEY constraint enforce automatically in PostgreSQL?', '{"A": "DEFAULT and CHECK", "B": "INDEX ONLY and NULLABLE", "C": "AUTO_INCREMENT and TEXT", "D": "UNIQUE and NOT NULL"}'::jsonb, 'D', 'Every primary key column is guaranteed to be unique and non-null, and PostgreSQL creates a unique B-tree index for it.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000055'::uuid, 'How many PRIMARY KEY constraints can a single PostgreSQL table have?', '{"A": "At most one (though it may span multiple columns as a composite PK)", "B": "Two", "C": "One per foreign key", "D": "Unlimited"}'::jsonb, 'A', 'A table can have only one primary key constraint, plus any number of UNIQUE constraints.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'What does a FOREIGN KEY constraint enforce?', '{"A": "Encryption of the column", "B": "Referential integrity: every non-NULL FK value must match an existing PK/UNIQUE value in the referenced table", "C": "Uniqueness in the child table", "D": "Automatic sorting"}'::jsonb, 'B', 'Foreign keys prevent orphaned child rows pointing to non-existent parent records.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'What does ''ON DELETE CASCADE'' on a foreign key do when a parent row is deleted?', '{"A": "Automatically deletes all referencing child rows", "B": "Sets child FK to NULL", "C": "Deletes the parent table", "D": "Blocks deleting the parent"}'::jsonb, 'A', 'CASCADE propagates parent deletion down to dependent child rows (e.g., deleting an attempt deletes its attempt_questions).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'What does ''ON DELETE SET NULL'' do when a parent row is deleted?', '{"A": "Throws a constraint error", "B": "Sets the child FK to 0", "C": "Sets the child''s foreign key column to NULL while keeping the child row", "D": "Deletes child rows"}'::jsonb, 'C', 'For optional relationships like milestone_questions.node_id, SET NULL preserves the question if a roadmap node is removed.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'Which constraint guarantees that a column cannot hold a NULL value?', '{"A": "CHECK", "B": "UNIQUE", "C": "NOT NULL", "D": "DEFAULT"}'::jsonb, 'C', 'NOT NULL rejects any INSERT or UPDATE attempting to store NULL in that column.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'What does a CHECK constraint validate?', '{"A": "Foreign key existence", "B": "User permissions", "C": "A boolean expression that every inserted/updated row must satisfy (e.g., score BETWEEN 0 AND 8)", "D": "Index size"}'::jsonb, 'C', 'CHECK constraints enforce row-level domain rules at write time.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'Does creating a FOREIGN KEY in PostgreSQL automatically create an index on the child''s FK column?', '{"A": "Only for UUID FKs", "B": "Only with ON DELETE CASCADE", "C": "No; PostgreSQL creates indexes for PK/UNIQUE, NOT automatically for FK columns", "D": "Yes, always"}'::jsonb, 'C', 'You should explicitly create indexes on frequently queried FK columns (e.g., idx_milestone_questions_skill).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000055'::uuid, 'What is the difference between ''SERIAL / GENERATED ALWAYS AS IDENTITY'' and ''UUID DEFAULT gen_random_uuid()'' for primary keys?', '{"A": "UUIDs are always sequential", "B": "Identity generates compact sequential integers (4/8 bytes); UUID generates globally unique 128-bit IDs without central coordination", "C": "Identity keys cannot be referenced by FKs", "D": "UUIDs are 4 bytes"}'::jsonb, 'B', 'UUIDs prevent ID enumeration in APIs and allow distributed ID generation, while identity integers are smaller.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'How does ''ON DELETE RESTRICT'' differ from ''ON DELETE NO ACTION'' (default) in PostgreSQL?', '{"A": "They are 100% identical in all cases", "B": "NO ACTION deletes child rows", "C": "RESTRICT deletes parent silently", "D": "RESTRICT checks immediately during the DELETE statement and cannot be deferred; NO ACTION checks at statement/transaction end and can be DEFERRABLE"}'::jsonb, 'D', 'Both prevent deleting a referenced parent, differing only when constraints are marked DEFERRABLE.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'What error occurs if you try to insert a ''milestone_questions'' row with a ''skill_id'' that does not exist in ''skills''?', '{"A": "Silent NULL insertion", "B": "PostgreSQL raises a foreign key violation error (SQLSTATE 23503)", "C": "Truncates the table", "D": "Creates a placeholder skill row"}'::jsonb, 'B', 'Referential integrity rejects child inserts whose FK target does not exist.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'Why is naming constraints explicitly (e.g., ''CONSTRAINT uq_user_skill UNIQUE (user_id, skill_id)'') good practice?', '{"A": "Named constraints are faster", "B": "Flyway requires it", "C": "Unnamed constraints fail in PostgreSQL", "D": "Explicit names make error logs readable and allow future ALTER TABLE DROP CONSTRAINT migrations"}'::jsonb, 'D', 'Predictable constraint names avoid guessing auto-generated names in later migrations.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'How does a CHECK constraint behave when a column value is NULL (e.g., ''score INT CHECK (score BETWEEN 0 AND 8)'')?', '{"A": "Rejects NULL", "B": "Passes! CHECK fails ONLY when the expression evaluates to FALSE, not UNKNOWN (NULL)", "C": "Converts NULL to 0", "D": "Throws an exception"}'::jsonb, 'B', 'In SQL, CHECK passes on UNKNOWN, so a nullable score with CHECK(score BETWEEN 0 AND 8) still permits NULL.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'Why do we add ''CREATE INDEX idx_milestone_attempts_user_skill ON milestone_attempts(user_id, skill_id);''?', '{"A": "To speed up lookups filtering by user_id or (user_id, skill_id) without scanning the whole table", "B": "To enforce uniqueness", "C": "To reduce disk space", "D": "Because PostgreSQL requires it for FKs"}'::jsonb, 'A', 'A composite B-tree index on (user_id, skill_id) accelerates both user-only and user+skill queries.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000055'::uuid, 'Can a FOREIGN KEY reference a UNIQUE non-primary-key column in another table?', '{"A": "No, only Primary Keys", "B": "Yes, any column(s) backed by a PRIMARY KEY or UNIQUE constraint", "C": "Only within the same table", "D": "Yes, any column even without UNIQUE"}'::jsonb, 'B', 'SQL requires the referenced target columns to have a PK or UNIQUE constraint so the parent row is unambiguous.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'What happens when you delete a row from ''roadmap_nodes'' if ''milestone_questions.node_id'' has ''ON DELETE SET NULL''?', '{"A": "The questions are deleted too", "B": "The node is deleted and matching milestone_questions rows keep their skill_id while node_id becomes NULL", "C": "milestone_attempts is deleted", "D": "Delete is blocked"}'::jsonb, 'B', 'ON DELETE SET NULL gracefully detaches the optional subtopic tag without losing questions or attempt history.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'In PostgreSQL, can a B-tree index on ''(a, b)'' be used by a query filtering ONLY on ''b''?', '{"A": "Generally no (index-seek uses leftmost prefix ''a''); a separate index on (b) is needed for b-only lookups", "B": "Only with DESC", "C": "Only for UUIDs", "D": "Yes, always efficiently"}'::jsonb, 'A', 'Composite B-tree indexes obey the leftmost-prefix rule.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'What is a partial index in PostgreSQL (e.g., ''WHERE is_active = TRUE'')?', '{"A": "An index covering only rows matching a WHERE predicate, reducing index size and speeding up active-only queries", "B": "A broken index", "C": "A temporary index", "D": "An index on half a column"}'::jsonb, 'A', 'Partial indexes exclude inactive/historical rows, keeping the B-tree small and hot in memory.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'Why can missing an index on a child FK column cause severe lock contention when deleting or updating a parent row?', '{"A": "PostgreSQL must sequential-scan the child table to check for referencing rows (or cascade deletes), holding locks longer", "B": "Parent PK becomes corrupted", "C": "PostgreSQL refuses to delete parents without an index", "D": "Child table becomes read-only"}'::jsonb, 'A', 'Indexing child FKs makes parent DELETE/UPDATE referential checks O(log n) instead of full child scans.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'In PostgreSQL, why can a partial unique index ''CREATE UNIQUE INDEX ... ON milestone_attempts(user_id, skill_id) WHERE status = ''''IN_PROGRESS'''';'' enforce a rule that a normal UNIQUE constraint cannot?', '{"A": "It is faster to create", "B": "Normal UNIQUE doesn''t work on UUIDs", "C": "It allows unlimited COMPLETED/ABANDONED attempts per user+skill while guaranteeing at most ONE concurrent IN_PROGRESS attempt", "D": "It bypasses transactions"}'::jsonb, 'C', 'Partial unique indexes enforce conditional uniqueness (at most one active/in-progress row) directly in the database.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'How can you add a CHECK or NOT NULL constraint to a huge production table in PostgreSQL without blocking writes for minutes?', '{"A": "Drop and recreate the table", "B": "Use TRUNCATE first", "C": "ALTER TABLE ... ADD CONSTRAINT ... NOT VALID, then ALTER TABLE ... VALIDATE CONSTRAINT in a separate step", "D": "Run inside a single long lock"}'::jsonb, 'C', 'NOT VALID enforces the constraint for new writes immediately with minimal lock, and VALIDATE CONSTRAINT scans existing rows with only a SHARE UPDATE EXCLUSIVE lock.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000055'::uuid, 'Why can a B-tree index on a text/JSONB column fail if values are huge, and what index type does PostgreSQL provide for JSONB?', '{"A": "B-tree indexes JSONB keys individually by default", "B": "Hash index only", "C": "JSONB cannot be indexed", "D": "GIN (Generalized Inverted Index) indexes keys/values inside JSONB documents efficiently"}'::jsonb, 'D', 'GIN indexes support @>, ?, ?|, ?& containment and key-existence operators on JSONB.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000057'::uuid, 'What does ''CREATE INDEX CONCURRENTLY'' do in PostgreSQL, and what restriction applies to it?', '{"A": "Only works on empty tables", "B": "Builds the index in 1 millisecond", "C": "Builds an index without blocking concurrent writes (INSERT/UPDATE/DELETE), but cannot run inside a transaction block (so not directly in default transactional Flyway scripts)", "D": "Drops old indexes"}'::jsonb, 'C', 'Concurrent index builds avoid write locks but require non-transactional execution.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'primary-foreign-keys'), '70000000-0000-0000-0000-000000000056'::uuid, 'If Table A has a FK to Table B, and Table B has a FK to Table A (mutual dependency), how can rows be inserted in PostgreSQL?', '{"A": "Use ON DELETE CASCADE", "B": "Disable foreign keys globally", "C": "Insert one with NULL FK first and UPDATE, or declare one FK as DEFERRABLE INITIALLY DEFERRED inside a transaction", "D": "Impossible"}'::jsonb, 'C', 'Deferred FKs or two-step insert+update resolve circular FK dependencies cleanly.', 'ADVANCED', TRUE);

-- Skill: database-normalization
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000058'::uuid, 'What is the core requirement of First Normal Form (1NF)?', '{"A": "No foreign keys", "B": "Every table has 3 columns", "C": "All columns are VARCHAR", "D": "Every column holds atomic (indivisible) values, with no repeating groups or multi-valued lists in a single cell"}'::jsonb, 'D', '1NF eliminates repeating groups and ensures each cell contains a single atomic value.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000058'::uuid, 'Which table design violates First Normal Form (1NF)?', '{"A": "A junction table", "B": "A separate table for user phone numbers", "C": "A ''users'' table with a ''phone_numbers'' column storing ''9876543210, 9123456789''", "D": "A table with a UUID primary key"}'::jsonb, 'C', 'Storing multiple comma-separated phone numbers in one column violates atomicity.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000059'::uuid, 'What prerequisite must a table satisfy BEFORE checking Second Normal Form (2NF)?', '{"A": "It must already be in 1NF", "B": "It must have no foreign keys", "C": "It must be in 3NF", "D": "It must have a composite primary key"}'::jsonb, 'A', 'Normal forms are cumulative: 2NF requires 1NF first, and 3NF requires 2NF.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000059'::uuid, 'What does Second Normal Form (2NF) eliminate?', '{"A": "Atomic values", "B": "Partial dependencies (non-key columns depending on only PART of a composite primary key)", "C": "Indexes", "D": "Primary keys"}'::jsonb, 'B', 'Every non-key attribute must depend on the ENTIRE primary key, not just a subset of it.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000059'::uuid, 'If a table is in 1NF and has a SINGLE-column primary key (e.g., ''id''), is it automatically in 2NF?', '{"A": "No, never", "B": "Only if it has no nulls", "C": "Yes, because a single-column key cannot have a proper subset to cause partial dependency", "D": "Only for UUID keys"}'::jsonb, 'C', 'Partial dependencies can only arise when the primary key is composite (2+ columns).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'What does Third Normal Form (3NF) eliminate?', '{"A": "Foreign keys", "B": "Primary keys", "C": "Partial dependencies", "D": "Transitive dependencies (non-key columns depending on another non-key column)"}'::jsonb, 'D', 'In 3NF, every non-key column must depend directly on the key, the whole key (2NF), and nothing but the key (3NF).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'Why do we normalize relational databases?', '{"A": "To make tables have more columns", "B": "To disable constraints", "C": "To avoid joins", "D": "To reduce data redundancy and prevent insert, update, and delete anomalies"}'::jsonb, 'D', 'Normalization ensures each fact is stored in one authoritative place.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'What is intentional denormalization?', '{"A": "Forgetting to add primary keys", "B": "Deleting foreign keys", "C": "Violating 1NF accidentally", "D": "Deliberately duplicating/precomputing data in a controlled way to optimize read performance"}'::jsonb, 'D', 'Denormalization trades write complexity/redundancy for faster reads when joins become a bottleneck.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000058'::uuid, 'Why is ''milestone_questions.options'' stored as JSONB in this schema even though classic 1NF prefers separate rows?', '{"A": "JSONB is required for 3NF", "B": "Because each question always has an atomic fixed 4-option map read as a single unit and never queried independently by option", "C": "Separate rows are illegal", "D": "PostgreSQL cannot store 4 rows"}'::jsonb, 'B', 'Pragmatic PostgreSQL design uses JSONB for self-contained value objects like MCQ option maps while keeping FKs normalized.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000059'::uuid, 'Consider ''enrollment(student_id, course_id, grade, course_title)'' with PK (student_id, course_id). Which normal form is violated?', '{"A": "2NF, because course_title depends only on course_id (part of the composite PK)", "B": "None", "C": "1NF", "D": "3NF only"}'::jsonb, 'A', 'Moving course_title to a ''courses(course_id, course_title)'' table resolves the 2NF partial dependency.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'Consider ''employees(emp_id, dept_id, dept_location)'' with PK emp_id. Which normal form is violated?', '{"A": "1NF", "B": "2NF", "C": "3NF, because dept_location depends on non-key column dept_id (emp_id -> dept_id -> dept_location)", "D": "None"}'::jsonb, 'C', 'This is a transitive dependency; dept_location belongs in a ''departments'' table.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'What is an ''update anomaly'' in an unnormalized table?', '{"A": "An index lock", "B": "Having to update the same fact (e.g., category name) in multiple duplicated rows, risking inconsistency if one is missed", "C": "A NULL value", "D": "A syntax error in UPDATE"}'::jsonb, 'B', 'Duplicated facts can diverge when updated partially.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'What is a ''deletion anomaly''?', '{"A": "Accidentally deleting a table", "B": "ON DELETE CASCADE failing", "C": "Deleting a record (e.g., the last student in a course) unintentionally destroys unrelated facts (e.g., the course''s title and credits)", "D": "Slow DELETE performance"}'::jsonb, 'C', 'Bundling independent entities in one table causes loss of one entity when the other is deleted.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'What is an ''insertion anomaly''?', '{"A": "Inserting duplicate IDs", "B": "Foreign key mismatch", "C": "Inability to record one entity (e.g., a new skill category) without inventing a dummy record for another entity (e.g., a fake skill)", "D": "Type conversion error"}'::jsonb, 'C', 'Mixing two entity types in one table blocks inserting one independently of the other.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000058'::uuid, 'If a table has columns ''tag1, tag2, tag3'' for a skill, why does that violate 1NF?', '{"A": "It violates 3NF only", "B": "It creates a repeating group across numbered columns, limiting tags to 3 and complicating searches", "C": "Because columns are named tag1..3", "D": "It uses too few columns"}'::jsonb, 'B', 'Fixed repeating column groups should be normalized into a child ''skill_tags'' table.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'In ''milestone_attempts'', storing ''score'' (0–8) alongside ''milestone_attempt_questions.is_correct'' is an example of:', '{"A": "1NF violation", "B": "2NF violation", "C": "Controlled denormalization (caching the computed aggregate score on the attempt for fast history reads)", "D": "A bug"}'::jsonb, 'C', 'Caching computed summary columns (updated atomically on submit) avoids recounting child rows on every dashboard load.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000059'::uuid, 'When checking 2NF, must we consider ALL candidate keys, not just the chosen Primary Key?', '{"A": "Only integer keys", "B": "Only foreign keys", "C": "Yes; formal 2NF checks non-prime attributes against every candidate key", "D": "No, only the Primary Key"}'::jsonb, 'C', 'A non-prime attribute (not part of any candidate key) must not partially depend on any candidate key.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'When is denormalization justified in production systems?', '{"A": "Only after profiling shows join/aggregation bottlenecks on read-heavy workloads, with a plan to keep duplicated data in sync", "B": "Never", "C": "Always in PostgreSQL", "D": "Before any query is measured"}'::jsonb, 'A', 'Normalize first for correctness; denormalize selectively for proven read performance needs.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'How does Boyce-Codd Normal Form (BCNF) strengthen 3NF?', '{"A": "BCNF is weaker than 3NF", "B": "BCNF forbids foreign keys", "C": "BCNF allows partial dependencies", "D": "BCNF requires that for every non-trivial functional dependency X -> Y, X must be a superkey (eliminating dependencies where a non-key determines part of a composite candidate key)"}'::jsonb, 'D', '3NF allows X -> A if A is prime (part of a candidate key); BCNF closes that loophole.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'In ''milestone_questions'', having BOTH ''skill_id'' (NOT NULL) and ''node_id'' (nullable FK to roadmap_nodes, which maps back to skill via skill_roadmaps) introduces what trade-off?', '{"A": "Direct skill_id avoids a 2-table join on every quiz start, at the cost of requiring seeding/code to keep node_id consistent with skill_id", "B": "PostgreSQL rejects both columns", "C": "node_id cannot be indexed", "D": "It violates 1NF"}'::jsonb, 'A', 'Direct skill_id makes skill-level queries fast and supports questions with node_id = NULL, while seed validation ensures node_id belongs to skill_id.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000059'::uuid, 'If a table has overlapping composite candidate keys (A, B) and (B, C), why can it satisfy 3NF yet still violate BCNF?', '{"A": "B is NULL", "B": "If A -> C holds (or C -> A), C is a prime attribute so 3NF permits it, but A is not a superkey so BCNF is violated", "C": "It violates 1NF", "D": "It cannot; 3NF and BCNF are identical"}'::jsonb, 'B', 'Overlapping candidate keys create the classic 3NF-vs-BCNF distinction.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'In PostgreSQL, what feature lets you keep normalized base tables while still serving pre-joined/aggregated reads quickly?', '{"A": "TRUNCATE", "B": "MATERIALIZED VIEW (refreshed on schedule or trigger)", "C": "CHECK constraints", "D": "JSONB casting"}'::jsonb, 'B', 'Materialized views store precomputed query results on disk without denormalizing the source tables.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000058'::uuid, 'Why is storing derived age (''age INT'') instead of ''birth_date DATE'' a normalization/maintenance issue?', '{"A": "Derived attributes change over time without any row update, becoming stale; store the canonical ''birth_date'' instead", "B": "INT cannot hold age", "C": "DATE cannot be indexed", "D": "It violates 1NF"}'::jsonb, 'A', 'Time-dependent derived values become inaccurate immediately as time passes.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'database-normalization'), '70000000-0000-0000-0000-000000000060'::uuid, 'In OLTP (transactional) vs OLAP (analytical/warehouse) schemas, why do OLTP systems favor 3NF while OLAP systems use Star/Snowflake schemas?', '{"A": "Star schemas use 5NF", "B": "OLTP optimizes write integrity and small row updates (3NF); OLAP optimizes massive read aggregations with fewer joins (denormalized fact/dimension tables)", "C": "OLAP does not support SQL", "D": "OLTP cannot run SELECT"}'::jsonb, 'B', 'OLTP and OLAP workloads have opposite read/write and consistency/throughput trade-offs.', 'ADVANCED', TRUE);

-- Skill: transactions-acid-properties
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'Which SQL command permanently saves all changes made in the current transaction?', '{"A": "APPLY", "B": "SAVE", "C": "COMMIT", "D": "END"}'::jsonb, 'C', 'COMMIT makes all statements in the transaction durable and visible to other sessions.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'Which SQL command undoes all changes made since the transaction began?', '{"A": "ROLLBACK", "B": "REVERT", "C": "CANCEL", "D": "UNDO"}'::jsonb, 'A', 'ROLLBACK aborts the transaction and restores the database to its pre-transaction state.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'What is a SAVEPOINT inside a SQL transaction?', '{"A": "A named marker inside a transaction allowing partial rollback via ROLLBACK TO savepoint_name", "B": "A full database backup", "C": "A read-only lock", "D": "An auto-commit toggle"}'::jsonb, 'A', 'Savepoints allow rolling back part of a transaction without discarding earlier work in the same transaction.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000062'::uuid, 'What does the ''A'' (Atomicity) in ACID stand for?', '{"A": "All-or-nothing: either every operation in the transaction succeeds or none take effect", "B": "Automatic indexing", "C": "Asynchronous execution", "D": "Always fast"}'::jsonb, 'A', 'Atomicity ensures partial failures roll back completely.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000062'::uuid, 'What does the ''D'' (Durability) in ACID guarantee?', '{"A": "Deleted rows are kept forever", "B": "Data is compressed", "C": "Once a transaction is committed, its changes survive crashes and power loss (via WAL/disk)", "D": "Database runs without RAM"}'::jsonb, 'C', 'PostgreSQL writes changes to the Write-Ahead Log (WAL) before acknowledging COMMIT.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000062'::uuid, 'What does the ''C'' (Consistency) in ACID mean?', '{"A": "Columns have consistent names", "B": "Every server has the same clock", "C": "Queries return the same rows forever", "D": "A transaction transitions the database from one valid state to another, satisfying all constraints, FKs, and invariants"}'::jsonb, 'D', 'Constraints, triggers, and application invariants remain valid before and after every committed transaction.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What does the ''I'' (Isolation) in ACID control?', '{"A": "User authentication", "B": "Network firewall rules", "C": "How concurrent transactions see (or are shielded from) each other''s uncommitted/concurrent changes", "D": "Disk partitioning"}'::jsonb, 'C', 'Isolation levels trade concurrency overhead against read anomalies.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What is a ''dirty read''?', '{"A": "Reading NULL values", "B": "Reading stale cached HTML", "C": "Reading uncommitted data written by another transaction that might later roll back", "D": "Reading corrupted disk sectors"}'::jsonb, 'C', 'PostgreSQL''s MVCC never allows dirty reads, even at READ UNCOMMITTED (which behaves like READ COMMITTED).', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'In Spring Boot, when a ''@Transactional'' method throws an unchecked RuntimeException, what does Spring do by default?', '{"A": "Rolls back the transaction", "B": "Commits the partial changes", "C": "Retries 3 times", "D": "Ignores the exception"}'::jsonb, 'A', 'Spring rolls back by default on unchecked (RuntimeException/Error) exceptions, and commits on checked exceptions unless rollbackFor is set.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'In PostgreSQL, what happens if a SQL statement fails with an error (e.g., duplicate key) inside an active transaction?', '{"A": "The transaction enters an ''aborted'' state and rejects further commands until ROLLBACK (or ROLLBACK TO SAVEPOINT)", "B": "You can ignore it and keep running more statements", "C": "PostgreSQL auto-commits prior statements", "D": "The server restarts"}'::jsonb, 'A', 'PostgreSQL requires rolling back the aborted transaction (or rolling back to a savepoint) before issuing more queries.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000062'::uuid, 'Why MUST creating a ''milestone_attempts'' row and its 8 ''milestone_attempt_questions'' rows happen in ONE transaction?', '{"A": "To enable JSONB", "B": "To make it run faster", "C": "PostgreSQL forbids inserting into two tables separately", "D": "Atomicity: if inserting the 8 questions fails, the attempt row must also roll back so no 0-question attempt persists"}'::jsonb, 'D', 'A single @Transactional block guarantees either attempt + all 8 questions are saved, or neither is.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What is the default transaction isolation level in PostgreSQL?', '{"A": "REPEATABLE READ", "B": "READ UNCOMMITTED", "C": "READ COMMITTED", "D": "SERIALIZABLE"}'::jsonb, 'C', 'PostgreSQL defaults to READ COMMITTED, where each statement sees data committed before that statement started.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What is a ''non-repeatable read''?', '{"A": "Reading uncommitted data", "B": "A deadlock", "C": "Reading the same row twice within one transaction and seeing different values because another transaction committed an UPDATE in between", "D": "A query that fails on retry"}'::jsonb, 'C', 'READ COMMITTED allows non-repeatable reads; REPEATABLE READ prevents them.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What is a ''phantom read''?', '{"A": "Reading NULLs", "B": "A slow query", "C": "Re-running a range query within a transaction and seeing new/removed rows committed by another transaction", "D": "Reading a deleted table"}'::jsonb, 'C', 'In standard SQL, SERIALIZABLE prevents phantoms; in PostgreSQL''s snapshot MVCC, REPEATABLE READ already prevents phantom reads too.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What is the difference between pessimistic locking (''SELECT ... FOR UPDATE'') and optimistic locking (''@Version'')?', '{"A": "Pessimistic locks rows at read time to block concurrent writers; optimistic lets readers proceed and checks a version counter at commit/update time", "B": "Optimistic locking blocks all readers", "C": "Pessimistic locking requires no transactions", "D": "They are identical"}'::jsonb, 'A', 'Use pessimistic locking under high contention (e.g., concurrent attempt creation) and optimistic locking under low contention.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'In PostgreSQL psql or JDBC, what is ''autocommit'' mode?', '{"A": "Disabled by default in psql", "B": "Commits happen once per hour", "C": "Each individual SQL statement is automatically wrapped in its own transaction and committed immediately", "D": "Transactions never roll back"}'::jsonb, 'C', 'Unless BEGIN is issued (or autocommit=false in JDBC/@Transactional), every standalone statement commits on completion.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000062'::uuid, 'How does PostgreSQL Write-Ahead Logging (WAL) guarantee Durability without flushing every random data page on every COMMIT?', '{"A": "It disables crashes", "B": "Sequential appends to the WAL file are flushed to disk on COMMIT; dirty heap pages can be flushed lazily later", "C": "It writes CSV files", "D": "It keeps everything in RAM only"}'::jsonb, 'B', 'Sequential WAL writes are much faster than random page writes while still enabling crash recovery.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What causes a database deadlock between Transaction T1 and Transaction T2?', '{"A": "A missing index", "B": "Too many rows", "C": "T1 holds lock A and waits for lock B, while T2 holds lock B and waits for lock A", "D": "Both running SELECT"}'::jsonb, 'C', 'PostgreSQL detects the lock cycle automatically and aborts one transaction so the other can proceed; consistent lock ordering prevents deadlocks.', 'INTERMEDIATE', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'Under READ COMMITTED, if two concurrent requests both check ''MAX(attempt_number) = 0'' for the same user+skill and try to insert attempt_number = 1, what happens if there is NO UNIQUE constraint?', '{"A": "Both succeed, creating TWO duplicate attempt_number = 1 rows (a classic TOCTOU / write-skew race condition)", "B": "PostgreSQL blocks the second one automatically", "C": "Second one updates the first", "D": "Deadlock error"}'::jsonb, 'A', 'Without a UNIQUE constraint or parent lock (e.g., locking user/skill or advisory lock), READ COMMITTED allows both concurrent transactions to read max=0 and insert attempt 1.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'How does PostgreSQL''s SERIALIZABLE isolation level differ from lock-based 2PL?', '{"A": "It disables MVCC", "B": "PostgreSQL uses SSI (Serializable Snapshot Isolation), detecting dangerous read-write dependency cycles without blocking readers", "C": "PostgreSQL runs transactions one-by-one on 1 CPU", "D": "PostgreSQL locks the entire database"}'::jsonb, 'B', 'SSI throws SQLSTATE 40001 (serialization_failure) when a cycle is detected, which applications should retry.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000061'::uuid, 'Why is keeping external HTTP calls or slow AI/email calls INSIDE a database ''@Transactional'' block dangerous?', '{"A": "It holds a precious DB connection from HikariCP and row locks open for seconds, exhausting the connection pool under load", "B": "PostgreSQL cancels the connection after 100ms", "C": "Java forbids HTTP inside @Transactional", "D": "HTTP rolls back SQL"}'::jsonb, 'A', 'Keep DB transactions short and focused purely on database state; perform external I/O before or after the transaction.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'Under REPEATABLE READ in PostgreSQL, what happens if Transaction A and B both try to UPDATE the same row concurrently?', '{"A": "Both overwrite each other silently", "B": "B succeeds with A''s values", "C": "B waits for A; if A commits, B fails with ''ERROR: could not serialize access due to concurrent update'' (40001)", "D": "A rolls back"}'::jsonb, 'C', 'First-committer-wins under REPEATABLE READ aborts the second writer with a serialization error.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000062'::uuid, 'In PostgreSQL, are DDL statements like ''CREATE TABLE'' and ''ALTER TABLE'' transactional?', '{"A": "Only CREATE TABLE is transactional", "B": "Yes! Almost all DDL in PostgreSQL is transactional and rolls back cleanly if a migration fails partway", "C": "No, they auto-commit immediately", "D": "Only inside Flyway"}'::jsonb, 'B', 'PostgreSQL''s transactional DDL means a failed Flyway migration rolls back cleanly instead of leaving half-created tables.', 'ADVANCED', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'transactions-acid-properties'), '70000000-0000-0000-0000-000000000063'::uuid, 'What is ''SELECT ... FOR UPDATE SKIP LOCKED'' typically used for in PostgreSQL?', '{"A": "Implementing high-throughput job/task queues where workers claim unlocked rows without blocking each other", "B": "Bypassing foreign keys", "C": "Skipping NULLs", "D": "Skipping corrupted rows"}'::jsonb, 'A', 'SKIP LOCKED lets multiple worker threads pull distinct pending jobs concurrently without contention.', 'ADVANCED', TRUE);

-- Skill: how-internet-works
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'how-internet-works'), '70000000-0000-0000-0000-000000000064'::uuid, 'What is the primary job of DNS (Domain Name System)?', '{"A": "Compressing images", "B": "Translating human-readable domain names (e.g., api.example.com) into IP addresses", "C": "Encrypting HTTP traffic", "D": "Assigning port numbers"}'::jsonb, 'B', 'DNS acts as the internet''s directory, mapping domain names to IPv4/IPv6 addresses.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
VALUES ((SELECT id FROM skills WHERE slug = 'how-internet-works'), '70000000-0000-0000-0000-000000000064'::uuid, 'How many bits are in an IPv4 address vs an IPv6 address?', '{"A": "Both are 64 bits", "B": "IPv4: 16 bits, IPv6: 32 bits", "C": "IPv4: 64 bits, IPv6: 128 bits", "D": "IPv4: 32 bits, IPv6: 128 bits"}'::jsonb, 'D', 'IPv4 uses 32-bit addresses (~4.3 billion); IPv6 uses 128-bit addresses to solve address exhaustion.', 'BEGINNER', TRUE);
INSERT INTO milestone_questions (skill_id, node_id, question_text, options, correct_answer, explanation, difficulty, is_active)
